//! The `Browser` shared by the SQL engines: catalog queries, paging and staged
//! changes generated by `dialect` and run through the engine's `Driver`.

use std::collections::BTreeMap;
use std::sync::Arc;

use anyhow::{Context, Result};
use async_trait::async_trait;

use super::{statement_context, Browser, Driver, Engine};
use crate::dialect::{Dialect, SqlEngine};
use crate::model::*;

pub struct SqlBrowser {
    driver: Arc<dyn Driver>,
    dialect: Dialect,
}

/// First column of every row of the first result set.
fn first_column(results: Vec<QueryResult>) -> Vec<String> {
    results
        .into_iter()
        .find(|r| r.has_rows)
        .map(|r| r.rows.into_iter().filter_map(|mut row| row.swap_remove(0)).collect())
        .unwrap_or_default()
}

fn rows_of(results: Vec<QueryResult>) -> Vec<Vec<Cell>> {
    results.into_iter().find(|r| r.has_rows).map(|r| r.rows).unwrap_or_default()
}

pub async fn engine(cfg: &ConnectionConfig, driver: Arc<dyn Driver>, dialect: Dialect) -> Result<Engine> {
    let one = |sql: &'static str| {
        let driver = driver.clone();
        async move { anyhow::Ok(first_column(driver.query(sql).await?).pop().unwrap_or_default()) }
    };
    let server_version = one(dialect.version_sql()).await?;
    let schema = one(dialect.current_schema_sql()).await?;
    let database = match dialect.0 {
        SqlEngine::Postgres => one("SELECT current_database()").await?,
        SqlEngine::Mysql => schema.clone(),
        SqlEngine::Sqlite => cfg.file_path.clone(),
    };
    Ok(Engine {
        browser: Arc::new(SqlBrowser { driver: driver.clone(), dialect }),
        driver,
        server_version,
        database,
        schema,
        read_only: false,
    })
}

impl SqlBrowser {
    async fn query(&self, sql: &str) -> Result<Vec<QueryResult>> {
        self.driver.query(sql).await.map_err(|e| statement_context(e, sql))
    }
}

#[async_trait]
impl Browser for SqlBrowser {
    async fn list_databases(&self) -> Result<Vec<String>> {
        match self.dialect.databases_sql() {
            Some(sql) => Ok(first_column(self.query(sql).await?)),
            None => Ok(Vec::new()),
        }
    }

    async fn list_schemas(&self) -> Result<Vec<String>> {
        Ok(first_column(self.query(self.dialect.schemas_sql()).await?))
    }

    async fn list_tables(&self, schema: &str) -> Result<Vec<TableInfo>> {
        Ok(rows_of(self.query(&self.dialect.tables_sql(schema)).await?)
            .into_iter()
            .map(|mut row| TableInfo {
                kind: row.pop().flatten().unwrap_or_else(|| "table".into()).to_lowercase(),
                name: row.pop().flatten().unwrap_or_default(),
            })
            .collect())
    }

    async fn table_columns(&self, schema: &str, table: &str) -> Result<Vec<ColumnInfo>> {
        Ok(rows_of(self.query(&self.dialect.columns_sql(schema, table)).await?)
            .into_iter()
            .map(|row| {
                let mut it = row.into_iter();
                let mut next = || it.next().flatten();
                ColumnInfo {
                    name: next().unwrap_or_default(),
                    data_type: next().unwrap_or_default(),
                    nullable: next().as_deref() != Some("NO"),
                    default: next(),
                    is_primary_key: next().as_deref() == Some("YES"),
                }
            })
            .collect())
    }

    async fn schema_columns(&self, schema: &str) -> Result<BTreeMap<String, Vec<String>>> {
        let mut map: BTreeMap<String, Vec<String>> = BTreeMap::new();
        for row in rows_of(self.query(&self.dialect.schema_columns_sql(schema)).await?) {
            let mut it = row.into_iter();
            if let (Some(Some(table)), Some(Some(col))) = (it.next(), it.next()) {
                map.entry(table).or_default().push(col);
            }
        }
        Ok(map)
    }

    async fn fetch_rows(&self, req: &FetchRequest) -> Result<QueryResult> {
        let sql = self.dialect.select_page_sql(req)?;
        let mut result = self
            .query(&sql)
            .await?
            .into_iter()
            .find(|r| r.has_rows)
            .context("the query returned no result set")?;
        result.sql = sql;
        Ok(result)
    }

    async fn count_rows(&self, req: &FetchRequest) -> Result<u64> {
        let sql = self.dialect.count_sql(req)?;
        let count = first_column(self.query(&sql).await?).pop().unwrap_or_default();
        count.parse().context("unexpected COUNT(*) result")
    }

    async fn preview_changes(&self, set: &ChangeSet) -> Result<Vec<String>> {
        self.dialect.change_statements(set)
    }

    async fn commit_changes(&self, set: &ChangeSet) -> Result<u64> {
        let statements = self.dialect.change_statements(set)?;
        self.driver.execute_in_transaction(&statements).await
    }
}
